[2338] = { ender = { "npc", 6868 }, giver = { "npc", 6868 }, level = 42, name = "Translating the Journal", prev = { 2318 }, races = 8589934770, req = 37, text = "Let Jarkal borrow the necklace. In exchange, he will translate the journal for you.", zone = 1337 },
[2339] = { ender = { "npc", 6868 }, giver = { "npc", 6868 }, level = 44, name = "Find the Gems and Power Source", races = 8589934770, req = 37, text = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.From the journal, you know...* The ruby has been stashed in a barricaded Shadowforge area.* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.* The sapphire has been claimed by Grimlok, the trogg leader.", zone = 1337 },
