[2458] = { classes = 8, ender = { "npc", 7233 }, giver = { "npc", 3401 }, level = 20, name = "Deep Cover", prev = { 2460 }, races = 8589934770, req = 20, rewards = { 8066 }, text = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.When the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.These actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize." },
[2460] = { classes = 8, ender = { "npc", 3401 }, giver = { "npc", 3401 }, level = 20, name = "The Shattered Salute", races = 8589934770, req = 20, text = "Perform the Shattered Salute on Shenthul." },
[2478] = { classes = 8, ender = { "npc", 3401 }, giver = { "npc", 7233 }, level = 24, name = "Mission: Possible But Not Probable", races = 8589934770, req = 20, rewards = { 18160 }, text = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.Assassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction." },
[2479] = { classes = 8, ender = { "npc", 2391 }, giver = { "npc", 3401 }, level = 26, name = "Hinott's Assistance", prev = { 2478 }, races = 8589934770, req = 20, text = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.To get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!" },
[2480] = { classes = 8, ender = { "npc", 2391 }, giver = { "npc", 2391 }, level = 20, name = "Hinott's Assistance", prev = { 2479 }, races = 8589934770, req = 20, rewards = { 8095 }, text = "Wait for Serge Hinott to complete the cure." },
