[4740] = { ender = { "npc", 2930 }, giver = { "object", 175320 }, level = 18, name = "WANTED: Murkdeep!", races = 4294967373, req = 15, rewards = { 5315, 15403, 15404 }, text = "Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.Report the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.", zone = 148 },
[4742] = { ender = { "npc", 10299 }, giver = { "npc", 10299 }, level = 60, name = "Seal of Ascension", req = 57, text = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe.", zone = 1583 },
[4743] = { ender = { "npc", 10299 }, giver = { "npc", 10299 }, level = 60, name = "Seal of Ascension", prev = { 4742 }, req = 57, rewards = { 12344 }, text = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!", zone = 1583 },
[4763] = { ender = { "npc", 3649 }, giver = { "npc", 3649 }, level = 18, name = "The Blackwood Corrupted", races = 4294967373, req = 15, rewards = { 15204, 15202, 15203 }, text = "Fill the Empty Cleansing Bowl at the Auberdine Moonwell.Gather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.Mix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.Take the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.", zone = 148 },
