[7508] = { ender = { "npc", 14368 }, level = 60, name = "The Forging of Quel'Serrar", req = 60, text = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", zone = 2557 },
[7509] = { classes = 3, ender = { "npc", 14368 }, giver = { "npc", 14368 }, level = 60, name = "The Forging of Quel'Serrar", prev = { 7508 }, req = 60, rewards = { 18348 }, text = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.Do this and Quel'Serrar will be yours.", zone = 2159 },
[7541] = { ender = { "npc", 4047 }, giver = { "npc", 4047 }, level = 40, name = "Service to the Horde", races = 8589934770, req = 30, rewards = { 18585, 18586 }, zone = 15 },
[7583] = { classes = 256, ender = { "npc", 14463 }, giver = { "npc", 14463 }, level = 60, name = "Suppression", req = 60, rewards = { 18602 }, text = "Venture forth into the Tainted Scar and locate a Doomguard Commander.Use the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.Should you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar." },
[7601] = { classes = 256, ender = { "npc", 14470 }, giver = { "npc", 14469 }, level = 50, name = "What Niby Commands", req = 50, text = "Speak with Impsy in Felwood.{\"ox\":\"This quest has objectives in $$.\",\"sx\":\"This quest starts in $$.\",\"ex\":\"This quest ends in $$.\",\"sex\":\"This quest starts and ends in $$.\",\"osx\":\"This quest has objectives and starts in $$.\",\"oex\":\"This quest has objectives and ends in $$.\",\"osx_ey\":\"This quest has objectives and starts in $$ and ends in $$.\",\"oex_sy\":\"This quest has objectives and ends in $$ and starts in $$.\",\"sx_ey\":\"This quest starts in $$ and ends in $$.\",\"ox_sy\":\"This quest starts in $$ and has objectives in $$.\",\"ox_ey\":\"This quest has objectives in $$ and ends in $$.\",\"ox_sey\":\"This quest starts and ends in $$ and has objectives in $$.\",\"ox_sy_ez\":\"This quest starts in $$, has objectives in $$ and ends in $$.\"}" },
[7602] = { classes = 256, ender = { "npc", 14470 }, giver = { "npc", 14470 }, level = 55, name = "Flawless Fel Essence", prev = { 7601 }, req = 50, text = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.The Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.Recover the Flawless Fel Essences and return to Impsy in Felwood." },
[7603] = { classes = 256, ender = { "npc", 14469 }, giver = { "npc", 14470 }, level = 55, name = "Kroshius' Infernal Core", prev = { 7602 }, req = 50, rewards = { 18762 }, text = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.Return Kroshius' Infernal Core to Niby the Almighty in Felwood." },
[7604] = { ender = { "npc", 12944 }, level = 60, name = "A Binding Contract", req = 60, rewards = { 18592 }, text = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", zone = 1584 },
[7622] = { classes = 16, ender = { "npc", 14494 }, giver = { "npc", 14494 }, level = 60, name = "The Balance of Light and Shadow", req = 60, rewards = { 18659 }, text = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.You may view the Death Post to view how many Peasants have been slain." },
[7623] = { classes = 256, ender = { "npc", 9516 }, giver = { "npc", 14437 }, level = 58, name = "Lord Banehollow", req = 60, text = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.Use the potions to travel through Jaedenar, and speak with Lord Banehollow.{\"ox\":\"This quest has objectives in $$.\",\"sx\":\"This quest starts in $$.\",\"ex\":\"This quest ends in $$.\",\"sex\":\"This quest starts and ends in $$.\",\"osx\":\"This quest has objectives and starts in $$.\",\"oex\":\"This quest has objectives and ends in $$.\",\"osx_ey\":\"This quest has objectives and starts in $$ and ends in $$.\",\"oex_sy\":\"This quest has objectives and ends in $$ and starts in $$.\",\"sx_ey\":\"This quest starts in $$ and ends in $$.\",\"ox_sy\":\"This quest starts in $$ and has objectives in $$.\",\"ox_ey\":\"This quest has objectives in $$ and ends in $$.\",\"ox_sey\":\"This quest starts and ends in $$ and has objectives in $$.\",\"ox_sy_ez\":\"This quest starts in $$, has objectives in $$ and ends in $$.\"}" },
[7624] = { classes = 256, ender = { "npc", 9516 }, giver = { "npc", 9516 }, level = 58, name = "Ulathek the Traitor", prev = { 7623 }, req = 60, text = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar." },
[7625] = { classes = 256, ender = { "npc", 14437 }, giver = { "npc", 9516 }, level = 60, name = "Xorothian Stardust", prev = { 7624 }, req = 60, text = "Purchase Xorothian Stardust from Ur'dan. Bring it to Gorzeeki Wildeyes in the Burning Steppes." },
[7629] = { classes = 256, ender = { "npc", 14437 }, giver = { "npc", 14437 }, level = 60, name = "Imp Delivery", prev = { 7625 }, req = 60, text = "Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes." },
[7631] = { classes = 256, ender = { "npc", 14504 }, giver = { "npc", 14436 }, level = 60, name = "Dreadsteed of Xoroth", req = 60, text = "Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you." },
[7634] = { classes = 4, ender = { "npc", 14526 }, giver = { "npc", 14526 }, level = 60, name = "Ancient Sinew Wrapped Lamina", req = 60, rewards = { 18714 }, text = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood." },
[7635] = { classes = 4, ender = { "npc", 14525 }, giver = { "npc", 14525 }, level = 60, name = "A Proper String", req = 60, rewards = { 18724 }, text = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood." },
[7636] = { classes = 4, ender = { "npc", 14524 }, giver = { "npc", 14524 }, level = 60, name = "Stave of the Ancients", req = 60, rewards = { 18707 }, text = "You must find and destroy these four demonic corrupters:Simone the Seductress.Klinfran the Crazed.Solenor the Slayer.Artorius the Doombringer.Destroy these creatures and return to Vartrus the Ancient in Felwood with their heads.Refer to the Petrified Bark in your inventory for clues as to their whereabouts.You MUST complete this task by yourself." },
[7643] = { classes = 2, ender = { "npc", 14566 }, giver = { "npc", 928 }, level = 60, name = "Ancient Equine Spirit", races = 4294967373, req = 60, text = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it." },
[7644] = { classes = 2, ender = { "npc", 928 }, giver = { "npc", 14566 }, level = 60, name = "Blessed Arcanite Barding", prev = { 7643 }, races = 4294967373, req = 60, text = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." },
[7645] = { classes = 2, ender = { "npc", 2357 }, giver = { "npc", 2357 }, level = 60, name = "Manna-Enriched Horse Feed", races = 4294967373, req = 60, rewards = { 18775 }, text = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits.You also need to give her 50 gold to soothe her ruffled sensibilities." },
[7646] = { classes = 2, ender = { "npc", 928 }, giver = { "npc", 928 }, level = 60, name = "The Divination Scryer", prev = { 7644 }, races = 4294967373, req = 60, text = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." },
[7647] = { classes = 2, ender = { "npc", 14568 }, giver = { "npc", 928 }, level = 60, name = "Judgment and Redemption", prev = { 7646 }, races = 4294967373, req = 60, text = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger." },
