[7667] = { classes = 64, ender = { "npc", 13417 }, giver = { "npc", 13417 }, level = 60, name = "Material Assistance", races = 8589934770, req = 58, text = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond." },
