[7701] = { ender = { "npc", 14634 }, giver = { "object", 179827 }, level = 50, name = "WANTED: Overseer Maltorius", req = 45, rewards = { 19128, 19127 }, text = "Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.Slay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward.", zone = 51 },
[7703] = { ender = { "npc", 14325 }, giver = { "npc", 14325 }, level = 60, name = "Unfinished Gordok Business", req = 56, rewards = { 18366, 18367, 18368, 18369 }, text = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.", zone = 2557 },
[7704] = { level = 50, name = "Look at the Size of It!", req = 45, rewards = { 18951 }, text = "Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge.", zone = 51 },
[7721] = { ender = { "npc", 14637 }, giver = { "npc", 14637 }, level = 48, name = "Fuel for the Zapping", req = 45, rewards = { 19039 }, text = "Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there.", zone = 357 },
[7723] = { ender = { "npc", 14627 }, giver = { "npc", 14627 }, level = 49, name = "Curse These Fat Fingers", req = 45, rewards = { 19126 }, text = "Hansel Heavyhands wants you to kill 20 Heavy War Golems.The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge.", zone = 51 },
[7724] = { ender = { "npc", 14627 }, giver = { "npc", 14627 }, level = 49, name = "Fiery Menace!", req = 45, rewards = { 19125 }, text = "Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders.", zone = 51 },
[7727] = { ender = { "npc", 14627 }, giver = { "npc", 14627 }, level = 49, name = "Incendosaurs? Whateverosaur is More Like It", req = 45, rewards = { 19141 }, text = "Hansel Heavyhands wants you to kill 20 Incendosaurs.You will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs.", zone = 51 },
[7728] = { ender = { "npc", 14626 }, giver = { "object", 179827 }, level = 48, name = "STOLEN: Smithing Tuyere and Lookout's Spyglass", req = 45, rewards = { 19124, 19123 }, text = "Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts.", zone = 51 },
[7732] = { ender = { "npc", 7010 }, giver = { "npc", 7875 }, level = 48, name = "Zukk'ash Report", races = 8589934770, req = 39, rewards = { 19038, 19037 }, text = "Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar.", zone = 357 },
[7733] = { ender = { "npc", 7852 }, giver = { "npc", 7852 }, level = 48, name = "Improved Quality", races = 4294967373, req = 40, rewards = { 19041 }, text = "Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas.", zone = 357 },
