[7815] = { ender = { "npc", 14740 }, giver = { "npc", 14740 }, level = 50, name = "Snapjaws, Mon!", races = 8589934770, req = 44, rewards = { 19022 }, text = "Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 15 Saltwater Snapjaw turtles. Return to him when you have completed this task.", zone = 47 },
[7838] = { ender = { "npc", 14508 }, giver = { "npc", 14508 }, level = 55, name = "Arena Grandmaster", rewards = { 19024 } },
[7840] = { ender = { "npc", 14731 }, giver = { "npc", 14731 }, level = 49, name = "Lard Lost His Lunch", races = 8589934770, req = 44, rewards = { 19035 }, text = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.Lard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.", zone = 47 },
[7841] = { ender = { "npc", 14738 }, giver = { "npc", 14738 }, level = 48, name = "Message to the Wildhammer", races = 8589934770, req = 44, text = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands.", zone = 47 },
[7842] = { ender = { "npc", 14738 }, giver = { "npc", 14738 }, level = 48, name = "Another Message to the Wildhammer", prev = { 7841 }, races = 8589934770, req = 44, text = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.Gryphons are known to inhabit every region of the Hinterlands.", zone = 47 },
[7843] = { ender = { "npc", 14738 }, giver = { "npc", 14738 }, level = 50, name = "The Final Message to the Wildhammer", prev = { 7842 }, races = 8589934770, req = 44, rewards = { 19119 }, text = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.Beware of angry Wildhammer dwarves and unruly members of the Alliance.", zone = 47 },
[7845] = { ender = { "npc", 14757 }, giver = { "npc", 14736 }, level = 51, name = "Kidnapped Elder Torntusk!", races = 8589934770, req = 46, text = "Primal Torntusk at Raventusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands.{\"ox\":\"This quest has objectives in $$.\",\"sx\":\"This quest starts in $$.\",\"ex\":\"This quest ends in $$.\",\"sex\":\"This quest starts and ends in $$.\",\"osx\":\"This quest has objectives and starts in $$.\",\"oex\":\"This quest has objectives and ends in $$.\",\"osx_ey\":\"This quest has objectives and starts in $$ and ends in $$.\",\"oex_sy\":\"This quest has objectives and ends in $$ and starts in $$.\",\"sx_ey\":\"This quest starts in $$ and ends in $$.\",\"ox_sy\":\"This quest starts in $$ and has objectives in $$.\",\"ox_ey\":\"This quest has objectives in $$ and ends in $$.\",\"ox_sey\":\"This quest starts and ends in $$ and has objectives in $$.\",\"ox_sy_ez\":\"This quest starts in $$, has objectives in $$ and ends in $$.\"}", zone = 47 },
[7846] = { ender = { "npc", 14757 }, giver = { "npc", 14757 }, level = 51, name = "Recover the Key!", prev = { 7845 }, races = 8589934770, req = 46, text = "Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torn'tusk when you have recovered the key.", zone = 47 },
[7847] = { ender = { "npc", 14736 }, giver = { "npc", 14757 }, level = 51, name = "Return to Primal Torntusk", prev = { 7846 }, races = 8589934770, req = 46, rewards = { 19114, 19115 }, text = "Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue.{\"ox\":\"This quest has objectives in $$.\",\"sx\":\"This quest starts in $$.\",\"ex\":\"This quest ends in $$.\",\"sex\":\"This quest starts and ends in $$.\",\"osx\":\"This quest has objectives and starts in $$.\",\"oex\":\"This quest has objectives and ends in $$.\",\"osx_ey\":\"This quest has objectives and starts in $$ and ends in $$.\",\"oex_sy\":\"This quest has objectives and ends in $$ and starts in $$.\",\"sx_ey\":\"This quest starts in $$ and ends in $$.\",\"ox_sy\":\"This quest starts in $$ and has objectives in $$.\",\"ox_ey\":\"This quest has objectives in $$ and ends in $$.\",\"ox_sey\":\"This quest starts and ends in $$ and has objectives in $$.\",\"ox_sy_ez\":\"This quest starts in $$, has objectives in $$ and ends in $$.\"}", zone = 47 },
[7848] = { ender = { "npc", 14387 }, giver = { "npc", 14387 }, level = 60, name = "Attunement to the Core", req = 55, text = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", zone = 2717 },
[7849] = { ender = { "npc", 14741 }, giver = { "npc", 14741 }, level = 50, name = "Separation Anxiety", races = 8589934770, req = 46, rewards = { 19117, 19116 }, text = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.", zone = 47 },
[7850] = { ender = { "npc", 14736 }, giver = { "npc", 14736 }, level = 50, name = "Dark Vessels", races = 8589934770, req = 46, rewards = { 19118 }, text = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.", zone = 47 },
[7861] = { ender = { "npc", 14736 }, giver = { "object", 179913 }, level = 51, name = "Wanted: Vile Priestess Hexx and Her Minions", races = 8589934770, req = 46, rewards = { 19159, 19121 }, text = "You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.", zone = 47 },
[7862] = { ender = { "npc", 14736 }, giver = { "object", 179913 }, level = 51, name = "Job Opening: Guard Captain of Revantusk Village", races = 8589934770, req = 46, rewards = { 19120 }, text = "You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.Should you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.", zone = 47 },
